/**
 * `RollSource` selection (plan-voters.md §2).
 *
 * The bundled JSONs are the one source. `assets/roll/*.json` ships inside the
 * APK (generated by `scripts/generate-ward-bundles.ts` from the extracted
 * CSVs), so the roll is resident on a first-ever launch — no network round
 * trip, no cold-start fetch, no rules dependency for the base roll, and no
 * "offline" state that means "no data": the data *is* the app.
 *
 * There is deliberately no second source any more. A Firestore-backed
 * `RollSource` used to live beside this file "for re-seeding and comparison",
 * and nothing imported it — which made it a loaded gun rather than
 * documentation: wiring it up would have pulled ~6 900 documents across the
 * network on a path the app is specifically built never to take. It was
 * deleted with the rest of the Firestore port. The seeding scripts read
 * Firestore through the Admin SDK directly, so they never needed it.
 *
 * On the database side the rule is enforced, not merely observed: `voters` has
 * `.read` only at `voters/$docId`, so a bulk `/voters` read is denied whatever
 * the client asks for. What the app does fetch is `users/{uid}/voterEdits` —
 * the overlay — which is a handful of rows and is merged over these bundled
 * ones at render time.
 *
 * User edits never flow through a source at all — they are local overlays
 * (`lib/roll/overlay.ts`), local-first, mirrored to the account by
 * `lib/roll/sync.ts`.
 */
import { bundledSource } from '@/lib/roll/bundled-source';
import type { RollSource } from '@/lib/roll/types';

let active: RollSource | null = null;

/** The source every screen reads through. Memoised — one per session. */
export function getRollSource(): RollSource {
  active ??= bundledSource;
  return active;
}
